import{_ as i,a0 as o,w as l,s as r,ao as d,I as p,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"使用 Terminator 在一個窗口中運行多個終端 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Terminator 在一個窗口中運行多個終端 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Terminator 在一個窗口中運行多個終端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Terminator 在一個窗口中運行多個終端 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190909 How to use Terminator on Linux to run multiple terminals in one window","title":"使用 Terminator 在一個窗口中運行多個終端","tag":"201909","desc":""},"relativePath":"201909/20190909 How to use Terminator on Linux to run multiple terminals in one window.md","filePath":"[post].md"}'),c={name:"201909/20190909 How to use Terminator on Linux to run multiple terminals in one window.md"};function m(u,n,h,g,f,T){const s=o("Link");return l(),r("div",null,[n[15]||(n[15]=d(`<h1 id="使用-terminator-在一個窗口中運行多個終端" tabindex="-1">使用 Terminator 在一個窗口中運行多個終端 <a class="header-anchor" href="#使用-terminator-在一個窗口中運行多個終端" aria-label="Permalink to “使用 Terminator 在一個窗口中運行多個終端”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201909/30/233732j9jjx3xxuujopiuu.jpg" alt=""></p><blockquote><p>Terminator 為在單窗口中運行多個 GNOME 終端提供了一個選擇，讓你可以靈活地調整工作空間來適應你的需求。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/09/terminator-code-100810364-large.jpg" alt=""></p><p>如果你曾經希望可以排列多個終端並將它們組織在一個窗口中，那麼我們可能會給你帶來一個好消息。 Linux 的 Terminator 可以為你做到這一點。沒有問題！</p><h3 id="分割窗口" tabindex="-1">分割窗口 <a class="header-anchor" href="#分割窗口" aria-label="Permalink to “分割窗口”">​</a></h3><p>Terminator 最初打開像是一個單一窗口的終端窗口一樣。但是，一旦在該窗口中單擊鼠標，它將彈出一個選項，讓你可以靈活地進行更改。你可以選擇“水平分割”或“垂直分割”，將你當前所在的窗口分為兩個較小的窗口。實際上，菜單旁會有小的分割結果圖示（類似於 <code>=</code> and <code>||</code>），你可以根據需要重複拆分窗口。當然，你如果將整個窗口分為六個或九個以上，那麼你可能會發現它們太小而無法有效使用。</p><p>使用 ASCII 藝術來説明分割窗口的過程，你可能會看到類似以下的樣子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+-------------------+     +-------------------+     +-------------------+</span></span>
<span class="line"><span>|                   |     |                   |     |                   |</span></span>
<span class="line"><span>|                   |     |                   |     |                   |</span></span>
<span class="line"><span>|                   | ==&gt; |-------------------| ==&gt; |-------------------|</span></span>
<span class="line"><span>|                   |     |                   |     |         |         |</span></span>
<span class="line"><span>|                   |     |                   |     |         |         |</span></span>
<span class="line"><span>+-------------------+     +-------------------+     +-------------------+</span></span>
<span class="line"><span>  原始終端                       水平分割                   垂直分割</span></span></code></pre></div><p>另一種拆分窗口的方法是使用控制鍵組合，例如，使用 <code>Ctrl+Shift+e</code> 垂直分割窗口，使用 <code>Ctrl+Shift+o</code>（“o” 表示“打開”）水平分割窗口。</p><p>在 Terminator 分割完成後，你可以點擊任意窗口使用，並根據工作需求在窗口間移動。</p><h3 id="最大化窗口" tabindex="-1">最大化窗口 <a class="header-anchor" href="#最大化窗口" aria-label="Permalink to “最大化窗口”">​</a></h3><p>如果你想暫時忽略除了一個窗口外的其他窗口而只關注一個，你可以單擊該窗口，然後從菜單中選擇“最大化”選項。接着該窗口會撐滿所有空間。再次單擊並選擇“還原所有終端”可以返回到多窗口顯示。使用 <code>Ctrl+Shift+x</code> 將在正常和最大化設置之間切換。</p><p>窗口標籤上的窗口大小指示（例如 80x15）顯示了每行的字符數以及每個窗口的行數。</p><h3 id="關閉窗口" tabindex="-1">關閉窗口 <a class="header-anchor" href="#關閉窗口" aria-label="Permalink to “關閉窗口”">​</a></h3><p>要關閉任何窗口，請打開 Terminator 菜單，然後選擇“關閉”。其他窗口將自行調整佔用空間，直到你關閉最後一個窗口。</p><h3 id="保存你的自定義設置" tabindex="-1">保存你的自定義設置 <a class="header-anchor" href="#保存你的自定義設置" aria-label="Permalink to “保存你的自定義設置”">​</a></h3><p>將窗口分為多個部分後，將自定義的 Terminator 設置設置為默認非常容易。從彈出菜單中選擇“首選項”，然後從打開的窗口頂部的選項卡中選擇“佈局”。接着你應該看到列出了“新佈局”。只需單擊底部的“保存”，然後單擊右下角的“關閉”。Terminator 會將你的設置保存在 <code>~/.config/terminator/config</code> 中，然後每次使用到時都會使用該文件。</p><p>你也可以通過使用鼠標拉伸來擴大整個窗口。再説一次，如果要保留更改，請從菜單中選擇“首選項”，“佈局”，接着選擇“保存”和“關閉”。</p><h3 id="在保存的配置之間進行選擇" tabindex="-1">在保存的配置之間進行選擇 <a class="header-anchor" href="#在保存的配置之間進行選擇" aria-label="Permalink to “在保存的配置之間進行選擇”">​</a></h3><p>如果願意，你可以通過維護多個配置文件來設置多種 Terminator 窗口布局，重命名每個配置文件（如 <code>config-1</code>、<code>config-2</code>），接着在你想使用它時將它移動到 <code>~/.config/terminator/config</code>。這有一個類似執行此任務的腳本。它讓你在 3 個預配置的窗口布局之間進行選擇。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PS3=&#39;Terminator options: &#39;</span></span>
<span class="line"><span>options=(&quot;Split 1&quot; &quot;Split 2&quot; &quot;Split 3&quot; &quot;Quit&quot;)</span></span>
<span class="line"><span>select opt in &quot;\${options[@]}&quot;</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    case $opt in</span></span>
<span class="line"><span>        &quot;Split 1&quot;)</span></span>
<span class="line"><span>            config=config-1</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>        &quot;Split 2&quot;)</span></span>
<span class="line"><span>            config=config-2</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>        &quot;Split 3&quot;)</span></span>
<span class="line"><span>            config=config-3</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>        *)</span></span>
<span class="line"><span>            exit</span></span>
<span class="line"><span>            ;;</span></span>
<span class="line"><span>    esac</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd ~/.config/terminator</span></span>
<span class="line"><span>cp config config-</span></span>
<span class="line"><span>cp $config config</span></span>
<span class="line"><span>cd</span></span>
<span class="line"><span>terminator &amp;</span></span></code></pre></div><p>如果有用的話，你可以給選項一個比 <code>config-1</code> 更有意義的名稱。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Terminator 是設置多窗口處理相關任務的不錯選擇。如果你從未使用過它，那麼可能需要先使用 <code>sudo apt install terminator</code> 或 <code>sudo yum install -y terminator</code> 之類的命令進行安裝。</p><p>希望你喜歡使用 Terminator。還有，如另一個同名角色所説，“我會回來的！”</p><hr>`,27)),p("p",null,[n[1]||(n[1]=a("via: ",-1)),e(s,{href:"https://www.networkworld.com/article/3436784/how-to-use-terminator-on-linux-to-run-multiple-terminals-in-one-window.html"},{default:t(()=>[...n[0]||(n[0]=[a("https://www.networkworld.com/article/3436784/how-to-use-terminator-on-linux-to-run-multiple-terminals-in-one-window.html",-1)])]),_:1})]),p("p",null,[n[6]||(n[6]=a("作者：",-1)),e(s,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...n[2]||(n[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),n[7]||(n[7]=a(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...n[3]||(n[3]=[a("lujun9972",-1)])]),_:1}),n[8]||(n[8]=a(" 譯者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:t(()=>[...n[4]||(n[4]=[a("geekpi",-1)])]),_:1}),n[9]||(n[9]=a(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:t(()=>[...n[5]||(n[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[n[12]||(n[12]=a("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...n[10]||(n[10]=[a("LCTT",-1)])]),_:1}),n[13]||(n[13]=a(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:t(()=>[...n[11]||(n[11]=[a("Linux中國",-1)])]),_:1}),n[14]||(n[14]=a(" 榮譽推出",-1))])])}const x=i(c,[["render",m]]);export{w as __pageData,x as default};
